//! 🧫️ Native coroutine transitions preserve authored scope and every actual allocation through cancellation.
use super::*;
use semio_framework_os_spr as protocol;
use semio_framework_job::close_original_retained_step;
use semio_framework_os_store_replay::native_supersession::{NativeSupersessionFold,NativeSupersessionSource};
use crate::replacement_tests::{turn,stock,source_stock,clock};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner};
fn schedule(cutoff:Option<usize>){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let document=law["document"].as_str().unwrap();let events:Vec<_>=law["events"].as_array().unwrap().iter().enumerate().map(|(position,event)|{let transition=protocol::HistoryTransition::Supersede(protocol::TransitionSupersede{scope:event["scope"].as_str().map(str::to_owned),inputs:event["inputs"].as_array().unwrap().iter().map(|input|protocol::SupersededInput{target:MutationId(input["target"].as_str().unwrap().into()),replacement:if input["withdrawn"]==true{protocol::InputReplacement::Withdrawn}else{protocol::InputReplacement::Input{schema:input["schema"].as_str().unwrap().into(),payload:input["payload"].as_str().unwrap().as_bytes().to_vec()}}}).collect()});protocol::history_transition_envelope(&transition,&protocol::ArtifactId(document.into()),&protocol::ActorId("original-actor".into()),Vec::new(),protocol::HybridLogicalTimestamp::new(0,position as u64))}).collect();let pointers:Vec<_>=events.iter().map(|event|event.diff.payload.retained_bytes().contiguous_at(0).map(|bytes|bytes.as_ptr())).collect();let mut owner=NativeSupersessionFold::default();let mut table=semio_framework_os_store_replay::EffectiveSupersessions::new();let mut caller=OriginalJobFixtureCaller::admit(OperationId(998),Generation(18),source_stock(),clock,u64::MAX,16*1024*1024);let mut decoder=OriginalJobDecodeOwner::empty();let mut position=0;let mut complete=false;
 for step in 0..200000{if cutoff==Some(step){break}let source=events.get(position).map(|event|NativeSupersessionSource{event,previous:position.checked_sub(1).and_then(|at|events.get(at)),document,line:None});let no_grant=RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0};let original_table=table.len();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(no_grant,&mut decoder,|cx|owner.advance(source,&mut table,cx)));assert!(matches!(result,Ok(None)|Ok(Some(false))),"[DEBUG] refused original supersession turn={step} event={position} result={result:?}");assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(table.len(),original_table);
 let source=events.get(position).map(|event|NativeSupersessionSource{event,previous:position.checked_sub(1).and_then(|at|events.get(at)),document,line:None});let demand=owner.original_job_demand(4096).unwrap();match quoted_turn(&mut caller,&mut decoder,demand,|cx|owner.advance(source,&mut table,cx)){Some(true)=>position+=1,Some(false)=>{complete=true;break},None=>{}}
 if owner.active(){let mut foreign=OriginalJobFixtureCaller::admit(OperationId(998),Generation(18),source_stock(),clock,u64::MAX,16*1024*1024);let mut foreign_decoder=OriginalJobDecodeOwner::empty();let source=events.get(position).map(|event|NativeSupersessionSource{event,previous:position.checked_sub(1).and_then(|at|events.get(at)),document,line:None});let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn_with_decoder(stock(),&mut foreign_decoder,|cx|owner.advance(source,&mut table,cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));foreign.retire(stock());}}
 if cutoff.is_none(){assert!(complete,"[DEBUG] native supersession coroutine must finish at event={position} quote={:?}",owner.original_job_demand(4096));let actual:serde_json::Map<String,serde_json::Value>=table.iter().map(|(target,value)|(target.0.clone(),serde_json::Value::from(match &value.replacement{protocol::InputReplacement::Withdrawn=>"withdrawn",protocol::InputReplacement::Input{..}=>"input"}))).collect();assert_eq!(serde_json::Value::Object(actual),law["expected"]);}
 owner.begin_close();for _ in 0..200000{let demand=owner.close_demands(4096).unwrap();if quoted_turn(&mut caller,&mut decoder,demand,|cx|owner.close(cx)){break}}assert!(owner.terminal_is_empty());assert_eq!(events.iter().map(|event|event.diff.payload.retained_bytes().contiguous_at(0).map(|bytes|bytes.as_ptr())).collect::<Vec<_>>(),pointers);drop(owner);let mut table=ControlledRetirement::new(table).ok().unwrap();while !table.terminal_is_empty(){turn(&mut caller,&mut decoder,|cx|close_original_retained_step(cx,table.next_demand(cx.retained_grant().maximum_copy_bytes)?,|g|table.step(g)).map(|_|()));}for _ in 0..200000{if decoder.terminal_is_empty(){break}caller.turn(stock(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}assert!(decoder.terminal_is_empty());caller.retire(stock());
}
#[test]
fn native_supersession_scope_and_cancellation_match_json_oracle_and_original_physical_receipts(){schedule(None);let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for cutoff in law["cancelPrefixes"].as_array().unwrap(){schedule(Some(cutoff.as_u64().unwrap()as usize));}}

fn quoted_turn<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,demand:RetirementDemand,run:impl FnOnce(&mut StepContext<'_>)->Result<R,semio_framework_job::OriginalTurnFailure>)->R{
 let mut grant=stock();grant.maximum_copy_bytes=grant.maximum_copy_bytes.max(demand.copy_bytes);grant.maximum_capacity_bytes=grant.maximum_capacity_bytes.max(demand.capacity_bytes);grant.maximum_release_bytes=grant.maximum_release_bytes.max(demand.release_bytes);grant.maximum_depth=grant.maximum_depth.max(demand.depth);
 let before=caller.cumulative_receipt();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,run));let value=result.unwrap();let after=caller.cumulative_receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));value
}
